export type ParsedDepositLpInstruction<
  TProgram extends string = typeof ANTE_UP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    financeConfig: TAccountMetas[1];
    market: TAccountMetas[2];
    financeMarket: TAccountMetas[3];
    holding: TAccountMetas[4];
    paymentMint: TAccountMetas[5];
    paymentVault: TAccountMetas[6];
    ownerPayment: TAccountMetas[7];
    owner: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
    systemProgram: TAccountMetas[10];
  };
  data: DepositLpInstructionData;
};

export function parseDepositLpInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedDepositLpInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      financeConfig: getNextAccount(),
      market: getNextAccount(),
      financeMarket: getNextAccount(),
      holding: getNextAccount(),
      paymentMint: getNextAccount(),
      paymentVault: getNextAccount(),
      ownerPayment: getNextAccount(),
      owner: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getDepositLpInstructionDataDecoder().decode(instruction.data),
  };
}
